/**
 * Lightweight, self-contained Canvas Confetti for BNI Anniversary Celebration
 */
(function() {
    var confettiCanvas = null;
    var ctx = null;
    var particles = [];
    var animationFrame = null;

    function initCanvas() {
        if (!confettiCanvas) {
            confettiCanvas = document.createElement('canvas');
            confettiCanvas.id = 'bni-confetti-canvas';
            confettiCanvas.style.position = 'fixed';
            confettiCanvas.style.top = '0';
            confettiCanvas.style.left = '0';
            confettiCanvas.style.width = '100vw';
            confettiCanvas.style.height = '100vh';
            confettiCanvas.style.pointerEvents = 'none';
            confettiCanvas.style.zIndex = '99999';
            document.body.appendChild(confettiCanvas);
            ctx = confettiCanvas.getContext('2d');
            resize();
            window.addEventListener('resize', resize);
        }
    }

    function resize() {
        if (confettiCanvas) {
            confettiCanvas.width = window.innerWidth * window.devicePixelRatio;
            confettiCanvas.height = window.innerHeight * window.devicePixelRatio;
            ctx.scale(window.devicePixelRatio, window.devicePixelRatio);
        }
    }

    var colors = ['#F37021', '#FF9A3C', '#005E54', '#00A896', '#FFD700', '#FFFFFF', '#F72585'];

    function createParticle(x, y) {
        return {
            x: x,
            y: y,
            w: 8 + Math.random() * 8,
            h: 5 + Math.random() * 7,
            color: colors[Math.floor(Math.random() * colors.length)],
            vx: (Math.random() - 0.5) * 16,
            vy: (Math.random() - 1.2) * 18,
            rotation: Math.random() * 360,
            rotationSpeed: (Math.random() - 0.5) * 12,
            gravity: 0.35 + Math.random() * 0.2,
            opacity: 1,
            decay: 0.005 + Math.random() * 0.008
        };
    }

    function render() {
        if (!ctx) return;
        ctx.clearRect(0, 0, window.innerWidth, window.innerHeight);

        for (var i = 0; i < particles.length; i++) {
            var p = particles[i];
            p.x += p.vx;
            p.y += p.vy;
            p.vy += p.gravity;
            p.rotation += p.rotationSpeed;
            p.opacity -= p.decay;

            if (p.opacity > 0) {
                ctx.save();
                ctx.translate(p.x, p.y);
                ctx.rotate((p.rotation * Math.PI) / 180);
                ctx.fillStyle = p.color;
                ctx.globalAlpha = Math.max(0, p.opacity);
                ctx.fillRect(-p.w / 2, -p.h / 2, p.w, p.h);
                ctx.restore();
            }
        }

        particles = particles.filter(function(p) { return p.opacity > 0 && p.y < window.innerHeight + 50; });

        if (particles.length > 0) {
            animationFrame = requestAnimationFrame(render);
        } else {
            animationFrame = null;
        }
    }

    window.fireConfetti = function(count) {
        initCanvas();
        count = count || 120;
        var startX1 = window.innerWidth * 0.2;
        var startX2 = window.innerWidth * 0.8;
        var startY = window.innerHeight * 0.6;

        for (var i = 0; i < count; i++) {
            particles.push(createParticle(startX1, startY));
            particles.push(createParticle(startX2, startY));
            particles.push(createParticle(window.innerWidth * 0.5, startY - 50));
        }

        if (!animationFrame) {
            render();
        }
    };
})();
